import{_ as T,a0 as l,w as a,s as o,ao as n,I as s,x as r,a1 as p,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"用 NTP 把控時間（一）：使用概覽 | LCTT x X-CMD","titleTemplate":false,"description":"用 NTP 把控時間（一）：使用概覽 | LCTT (201704) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 NTP 把控時間（一）：使用概覽 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 NTP 把控時間（一）：使用概覽 | LCTT (201704) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201704/20170118 Arrive On Time With NTP -- Part 1- Usage Overview","title":"用 NTP 把控時間（一）：使用概覽","tag":"201704","desc":""},"relativePath":"201704/20170118 Arrive On Time With NTP -- Part 1- Usage Overview.md","filePath":"[post].md"}'),u={name:"201704/20170118 Arrive On Time With NTP -- Part 1- Usage Overview.md"};function P(N,t,m,d,f,w){const e=l("Link");return a(),o("div",null,[t[19]||(t[19]=n('<h1 id="用-ntp-把控時間-一-使用概覽" tabindex="-1">用 NTP 把控時間（一）：使用概覽 <a class="header-anchor" href="#用-ntp-把控時間-一-使用概覽" aria-label="Permalink to “用 NTP 把控時間（一）：使用概覽”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ntp-time.jpg?itok=zu8dqpki" alt="NTP" title="NTP"></p><p>這系列共三部分，首先，Chirs Binnie 探討了在一個合理的架構中 NTP 服務的重要性。</p><p>鮮有互聯網上的服務能如時間服務一樣重要。影響你係統計時的小問題可能需要一兩天才能被發現，而這些不期而遇的問題所帶來的連鎖反應幾乎總是讓人傷腦筋的。</p><p>設想你的備份服務器與網絡時間協議（NTP）服務器斷開連接，過了幾天，引起了幾小時的時間偏差。你的同事照常九點上班，發現需要大量帶寬的備份服務器消耗了所有網絡資源，這也就意味着他們在備份完成之前幾乎不能登錄工作台開始他們的日常工作。</p><p>這系列共三部分，首先，我將提供簡要介紹 NTP 來防止這種困境的發生。從郵件的時間戳到記錄你工作的進展，NTP 服務對於一個合理的架構是如此的重要。</p><p>可以把如此重要的 NTP 服務器（其他的服務器從此獲取時鐘數據）看做是倒置金字塔的底部，它被稱之為<ruby>一層<rt>Stratum 1</rt></ruby>服務器（也被稱為“<ruby>主<rt>primary</rt></ruby>”服務器）。這些服務器與國家級時間服務（稱為<ruby>零層<rt>Stratum 0</rt></ruby>，通常這些設備是是原子鐘和 GPS 鍾之類的裝置）直接交互。與之安全通訊的方法很多，例如通過衞星或者無線電。</p><p>令人驚訝的是，幾乎所有的大型企業都會連接<ruby>二層<rt>Stratum 2</rt></ruby>服務器（或“<ruby>次級<rt>secondary</rt></ruby>”服務器）而是不是主服務器。如你所料，二層服務器和一層直接同步。如果你覺得大公司可能有自己的本地 NTP 服務器（至少兩個，通常三個，為了災難恢復之用），這些就是三層服務器。這樣，三層服務器將連接上層預定義的次級服務器，負責任地傳遞時間給客户端和服務器，精確地反饋當前時間。</p>',8)),s("p",null,[t[1]||(t[1]=r("由簡單設計而構成的 NTP 可以工作的前提是——多虧了通過互聯網跨越了大範圍的地理距離——在確認時間完全準確之前，來回時間（包什麼時候發出和多少秒後被收到）都會被清楚記錄。設置電腦的時間的背後要比你想像的複雜得多，如果你不相信，那",-1)),p(e,{href:"http://www.ntp.org/ntpfaq/NTP-s-sw-clocks-quality.htm"},{default:i(()=>[...t[0]||(t[0]=[r("這神奇的網頁",-1)])]),_:1}),t[2]||(t[2]=r("值得一看。",-1))]),s("p",null,[t[4]||(t[4]=r("再次重提一遍，為了確保你的架構如預期般工作，NTP 是如此的關鍵，你的 NTP 與層次服務器之間的連接必須是完全可信賴並且能提供額外的冗餘，才能保持你的內部時鐘同步。在 ",-1)),p(e,{href:"http://support.ntp.org/bin/view/Servers/StratumOneTimeServers"},{default:i(()=>[...t[3]||(t[3]=[r("NTP 主站",-1)])]),_:1}),t[5]||(t[5]=r("有一個有用的一層服務器列表。",-1))]),t[20]||(t[20]=n('<p>正如你在列表所見，一些 NTP 一層服務器以 “ClosedAccount” 狀態運行；這些服務器需要事先接受才可以使用。但是隻要你完全按照他們的使用引導做，“OpenAccess” 服務器是可以用於輪詢使用的。而 “RestrictedAccess” 服務器有時候會因為大量客户端訪問或者輪詢間隙太小而受限。另外有時候也有一些專供某種類型的組織使用，例如學術界。</p><h3 id="尊重我的權威" tabindex="-1">尊重我的權威 <a class="header-anchor" href="#尊重我的權威" aria-label="Permalink to “尊重我的權威”">​</a></h3><p>在公共 NTP 服務器上，你可能發現遵從某些規則的使用規範。現在讓我們看看其中一些。</p><p>“iburst” 選項作用是如果在一個標準的輪詢間隔內沒有應答，客户端會發送一定數量的包（八個包而不是通常的一個）給 NTP 服務器。如果在短時間內呼叫 NTP 服務器幾次，沒有出現可辨識的應答，那麼本地時間將不會變化。</p><p>不像 “iburst” ，按照 NTP 服務器的通用規則， “burst” 選項一般不允許使用（所以不要用它！）。這個選項不僅在輪詢間隔發送大量包（明顯又是八個），而且也會在服務器能正常使用時這樣做。如果你在高層服務器持續發送包，甚至是它們在正常應答時，你可能會因為使用 “burst” 選項而被拉黑。</p><p>顯然，你連接服務器的頻率造成了它的負載差異（和少量的帶寬佔用）。使用 “minpoll” 和 “maxpoll” 選項可以本地設置頻率。然而，根據連接 NTP 服務器的規則，你不應該分別修改其默認的 64 秒和 1024 秒。</p><p>此外，需要提出的是客户應該重視那些請求時間的服務器發出的“<ruby>親一下就死（死亡之吻）<rt>Kiss-Of-Death</rt></ruby>” （KOD）消息。如果 NTP 服務器不想響應某個特定的請求，就像路由和防火牆技術那樣，那麼它最有可能的就是簡單地遺棄或吞沒任何相關的包。</p><p>換句話説，接受到這些數據的服務器並不需要特別處理這些包，簡單地丟棄這些它認為這不值得回應的包即可。你可以想像，這並不是特別好的做法，有時候禮貌地問客户是否中止或停止比忽略請求更為有效。因此，這種特別的包類型叫做 KOD 包。如果一個客户端被髮送了這種不受歡迎的 KOD 包，它應該記住這個發回了拒絕訪問標誌的服務器。</p><p>如果從該服務器收到不止一個 KOD 包，客户端會猜想服務器上發生了流量限速的情況（或類似的）。這種情況下，客户端一般會寫入本地日誌，提示與該服務器的交流不太順利，以備將來排錯之用。</p><p>牢記，出於顯而易見的原因，關鍵在於 NTP 服務器的架構應該是動態的。因此，不要給你的 NTP 配置硬編碼 IP 地址是非常重要的。通過使用 DNS 域名，個別服務器斷開網絡時服務仍能繼續進行，而 IP 地址空間也能重新分配，並且可引入簡單的負載均衡（具有一定程度的彈性）。</p><p>請別忘了我們也需要考慮呈指數增長的物聯網（IoT），這最終將包括數以億萬計的新裝置，意味着這些設備都需要保持正確時間。硬件賣家無意（或有意）設置他們的設備只能與一個提供者的（甚至一個） NTP 服務器連接終將成為過去，這是一個非常麻煩的問題。</p><p>你可能會想像，隨着買入和上線更多的硬件單元，NTP 基礎設施的擁有者大概不會為相關的費用而感到高興，因為他們正被沒有實際收入所困擾。這種情形並非杞人憂天。頭疼的問題多呢 -- 由於 NTP 流量導致基礎架構不堪重負 -- 這在過去幾年裏已發生過多次。</p><p>在下面兩篇文章裏，我將着重於一些重要的 NTP 安全配置選項和描述服務器的搭建。</p><hr>',14)),s("p",null,[t[7]||(t[7]=r("via: ",-1)),p(e,{href:"https://www.linux.com/learn/arrive-time-ntp-part-1-usage-overview"},{default:i(()=>[...t[6]||(t[6]=[r("https://www.linux.com/learn/arrive-time-ntp-part-1-usage-overview",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=r("作者：",-1)),p(e,{href:"https://www.linux.com/users/chrisbinnie"},{default:i(()=>[...t[8]||(t[8]=[r("CHRIS BINNIE",-1)])]),_:1}),t[12]||(t[12]=r(" 譯者：",-1)),p(e,{href:"https://github.com/XYenChi"},{default:i(()=>[...t[9]||(t[9]=[r("XYenChi",-1)])]),_:1}),t[13]||(t[13]=r(" 校對：",-1)),p(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[r("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=r("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[r("LCTT",-1)])]),_:1}),t[17]||(t[17]=r(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[r("Linux中國",-1)])]),_:1}),t[18]||(t[18]=r(" 榮譽推出",-1))])])}const x=T(u,[["render",P]]);export{C as __pageData,x as default};
